// Fonction pour corriger le texte mal encodé (UTF-8 lu comme Latin-1)
function fixEncoding(str) {
    if (!str || typeof str !== 'string') return str;

    try {
        // Étape 1: Convertir la chaîne mal affichée en Buffer (en utilisant Latin-1)
        const buffer = Buffer.from(str, 'latin1');

        // Étape 2: Re-interpréter ce Buffer en UTF-8
        return buffer.toString('utf-8');
    } catch (e) {
        return str;
    }
}

// Appliquer la correction sur tous les champs texte de votre item
for (const item of items) {
    for (const [key, value] of Object.entries(item.json)) {
        if (typeof value === 'string') {
            // Ne corriger que si le texte contient des signes suspects (Ù, Å, etc.)
            if (/[ÙÅÊËÈÍÎÏ]/.test(value)) {
                item.json[key] = fixEncoding(value);
            }
        }
    }
}

return items;

for (const item of items) {
    if (item.json.textPlain) {
        const text = item.json.textPlain;

        // Trouver la position de "De : ai@jbel-annour.ma"
        const index = text.indexOf("De : ai@jbel-annour.ma");

        if (index !== -1) {
            // Extraire le texte avant
            item.json.text_before_de = text.substring(0, index).trim();

        } else {
            // Si pas trouvé, garder tout le texte
            item.json.text_before_de = text;
        }
    }
}

return items;

// Texte d'entrée
const inputText = $json.subject;

// Expression régulière pour extraire les variables
const regex = /BC(\d{6,7})\/T(\d{4,5})\/(\d+)/;
const match = inputText.match(regex);

if (match) {
    // Extraction des trois variables
    const variable1 = match[1]; // 190245
    const variable2 = match[2]; // 2024  
    const variable3 = match[3]; // 1

    // Création de l'objet résultat
    const result = {
        numero_commande: 'BC' + variable1,
        tier: 'T' + variable2,
        id: variable3
    };

    console.log("Variables extraites :", result);
    return result;
} else {
    console.log("Aucune correspondance trouvée");
    return null;
}

const items = $input.all();

return items.map(item => {
  const reponse = (item.json.text_before_de ?? '').toString().trim();

  const prompt = `Tu es un classificateur binaire strict.

**Contexte** : Le PDG répond par email à une demande d'avance sur un bon de commande. Il faut déterminer s'il valide (accord) ou non la demande.

**Règles** :
1. Réponds uniquement par "oui" ou "non" en minuscules.
2. Considère comme OUI les mots suivants (et leurs variantes) :
   oui, ouais, yes, yep, ok, okay, d'accord, valide, valider, validé, valede, confirme, confirmer, confirmé, approuve, approuver, approuvé, accepte, accepter, accepté, موافق, نعم, تم, مؤكد, حاضر, c'est bon, ça marche, parfait, super, go, proceed, confirm, approved, accepted.
3. Tout le reste → non (par défaut).
4. Si la réponse contient un mot oui, réponds oui. Sinon, réponds non.
5. Aucune explication. Sortie stricte : oui ou non.

**Réponse utilisateur** : ${reponse}

La réponse doit être strictement : oui ou non, sans explication.`;

  return {
    json: {
      ...item.json,
      text_before_de: reponse,
      prompt
    }
  };
});

return $input.all().map(item => {
  const raw = item.json?.choices?.[0]?.message?.content ?? '';
  const content = String(raw).toLowerCase();

  let result = 'non'; // valeur par défaut

  // 1) Essai JSON propre
  try {
    const cleaned = content.replace(/```json|```/g, '').trim();
    const parsed = JSON.parse(cleaned);
    const val = (typeof parsed === 'string' ? parsed : parsed?.result ?? '')
      .toString().trim();
    if (val === 'oui' || val === 'non') result = val;
    else throw new Error('format inattendu');
  } catch (e) {
    // 2) Fallback regex : premier "oui" ou "non" trouvé
    const match = content.match(/\b(oui|non)\b/);
    if (match) result = match[1];
  }

  return {
    json: {
      output: {
        result: [result]
      }
    }
  };
});
